<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageContentVO;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder\MessageContentAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageContentAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class MessageContentAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getContent returns null on a freshly created holder.
         */
        public function testContentNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithMessageContentAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isContentAssigned());
            $this->assertNull($holder->getContent());
        }
}
class ImplWithMessageContentAttributeHolderUnitTest
{
  use MessageContentAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedContentRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultContent();
    }}
